  "{0}: “Bu kür seni {1} dövüş boyunca canavara çevirir. Testlerde çıkmaz… genelde.” Fiyatı {2}.\n\nKabul edersen vuruş, kondisyon, hız ve çene ciddi artar. Yakalanırsan 6 ay ile 2 yıl arası men, popülerlik kaybı ve sponsor iptali.": "{0}: “Este ciclo vai te transformar num monstro por {1} lutas. Não aparece nos testes… normalmente.” O preço é {2}.\n\nSe aceitar, sua trocação, cardio, velocidade e queixo sobem muito. Se for pego: suspensão de 6 meses a 2 anos, perda de popularidade e patrocinadores cancelados.",
  "Kabul et": "Aceitar",
  "Federasyona ihbar et": "Denunciar à comissão",
  "Kürü aldın. Aynada başka biri var. Sonraki {0} dövüşte çok güçlüsün… ama her dövüşten sonra test riski var.": "Você entrou no ciclo. Tem outra pessoa no espelho. Você estará muito forte nas próximas {0} lutas… mas cada luta traz risco de teste.",
  "Kibarca reddettin. Temiz bir kariyer, huzurlu bir uyku.": "Você recusou com educação. Uma carreira limpa, um sono tranquilo.",
  "Federasyona ihbar ettin. Basın seni “temiz sporun sesi” ilan etti. Popülerlik +2.": "Você denunciou à comissão. A imprensa te chamou de “a voz do esporte limpo”. Popularidade +2.",
  "💼 Sponsorluk Teklifi": "💼 Oferta de patrocínio",
  "Bahis": "Apostas",
  "\n\nAma bir bahis şirketi… Bazı taraftarların hoşuna gitmeyebilir.": "\n\nMas é uma casa de apostas… Alguns fãs podem não gostar.",
  "{0} seninle çalışmak istiyor. Şortunda logoları olacak, karşılığında {1} ödeyecekler.{2}": "{0} quer trabalhar com você. Os logos vão no seu calção e eles pagam {1}.{2}",
  "Pazarlık yap (+%50 dene)": "Negociar (tentar +50%)",
  " (Bazı taraftarlar tepkili: popülerlik -2)": " (Alguns fãs estão chateados: popularidade -2)",
  "{0} ile anlaştın. +{1}{2}": "Você assinou com {0}. +{1}{2}",
