  "{0} masadan kalktı. \"Başka dövüşçüler de var.\"": "{0} desistiu. \"Existem outros lutadores.\"",
  "Teklifi reddettin. İmajın temiz kaldı.": "Você recusou a oferta. Sua imagem continua limpa.",
  "Antrenmanda sparring partnerini uyuttuğun bir video 2 milyon izlendi. Yorumlar ikiye bölünmüş durumda. Ne paylaşırsın?": "Um vídeo seu nocauteando o parceiro de sparring chegou a 2 milhões de views. Os comentários estão divididos. O que você posta?",
