  "Görmezden gel": "Ignore",
  "Paylaşımın ortalığı yıktı. Rakipler cevap yazıyor, gazeteciler seni arıyor. Popülerlik +5.": "Seu post explodiu. Rivais respondendo, jornalistas ligando. Popularidade +5.",
  "Kibirli buldular. \"Önce bir kemer kazan\" yorumları ağır bastı. Popülerlik -3.": "Acharam arrogante. Comentários de \"primeiro ganhe um cinturão\" tomaram conta. Popularidade -3.",
  "Samimi mesajın sevildi. Popülerlik +2.": "Sua mensagem sincera foi adorada. Popularidade +2.",
  "Hiçbir şey yazmadın. Video kendi kendine yayılmaya devam etti. Popülerlik +1.": "Você não postou nada. O vídeo continuou se espalhando sozinho. Popularidade +1.",
  "🏟️ Salon Değiştirme Fırsatı": "🏟️ Uma chance de trocar de academia",
  "{0} baş antrenörü {1} seni takımında görmek istiyor (kalite {2}/10). Davetli olduğun için geçiş ücreti yarı fiyat: {3}.\n\nŞu anki hocan {4} (kalite {5}/10) seni sıfırdan yetiştirdi.": "O treinador-chefe da {0}, {1}, te quer na equipe (qualidade {2}/10). Como é um convite, a transferência sai pela metade: {3}.\n\nSeu treinador atual, {4} (qualidade {5}/10), te formou do zero.",
