  "Bahisçiler şokta: yılın sürprizlerinden biri!": "As casas de apostas em choque: uma das zebras do ano!",
  "Sürpriz galibiyetin tüm spor sayfalarında.": "Sua vitória zebra está em todas as páginas de esporte.",
  "Buna dövüş değil, savaş denir. {opp}’a saygılar.": "Aquilo não foi uma luta, foi uma guerra. Respeito a {opp}.",
  "İkimiz de kanadık. Seyirci parasının karşılığını aldı!": "Nós dois sangramos. Os fãs tiveram o que pagaram!",
  "“Yılın dövüşü” adaylarına girdiniz.": "Você está na conversa de “luta do ano”.",
  "Seyirciler ayakta, iki savaşçıyı da alkışladı.": "Os fãs aplaudem de pé os dois guerreiros.",
  "İlk profesyonel galibiyet! Bu anı ömrüm boyunca unutmayacağım.": "Minha primeira vitória profissional! Nunca vou esquecer este momento.",
  "Bir rüya başladı. Profesyonel olarak ilk zafer!": "Um sonho começou. Minha primeira vitória como profissional!",
  "Profesyonel kariyerine muhteşem bir başlangıç.": "Um começo espetacular na carreira profissional.",
  "Yerel basın “yeni bir yıldız doğuyor” başlığını attı.": "A imprensa local deu a manchete “nasce uma nova estrela”.",
  "{orgKisa}’a merhaba dedim! Bu organizasyonu sallayacağım.": "Olá, {orgKisa}! Vou sacudir esta organização.",
  "Yeni evime ilk hediyem bu galibiyet.": "Esta vitória é meu primeiro presente para a minha nova casa.",
  "{0} yöneticileri yeni transferlerinden memnun.": "Os executivos da {0} estão felizes com a nova contratação.",
  "Organizasyonun resmi hesabı seni “yılın transferi” diye paylaştı.": "A conta oficial da organização te chamou de “a contratação do ano”.",
  "{seri} maçtır kaybetmiyorum. Kim durduracak beni?": "Não perco há {seri} lutas. Quem vai me parar?",
  "Seri devam ediyor. Sıklette beni durduracak kimse yok.": "A sequência continua. Ninguém nesta categoria me para.",
  "Seri istatistikleri ekranlarda. Herkes kimin durduracağını tartışıyor.": "As estatísticas da sua sequência estão nas telas. Todos debatem quem vai te parar.",
  "Sıklette “yenilmez” etiketi sana yapışmaya başladı.": "O rótulo de “imbatível” começa a grudar em você na categoria.",
