  "Maçtan önce çok konuşuyordun {opp}. Şimdi sessiz kalmak sana yakışıyor.": "Você falou muito antes da luta, {opp}. Agora o silêncio te cai bem.",
  "{opp}, laf yetmiyor. Bunu öğrenmiş olmalısın.": "{opp}, falar não basta. Você já deve ter aprendido.",
  "Taraftarlar bu cevabı çok sevdi!": "Os fãs adoraram essa resposta!",
  "“Sözün bittiği yer” klibin viral oldu.": "Seu clipe de “onde as palavras acabam” viralizou.",
  "{opp} gibi sporcular bu sporu güzelleştiriyor. Kucaklaşmamız her şeyi anlatıyor.": "Atletas como {opp} deixam este esporte bonito. Nosso abraço diz tudo.",
  "Kafesteki kucaklaşmanız gecenin en güzel fotoğrafı oldu.": "O abraço de vocês no octógono foi a melhor foto da noite.",
  "Hesap kapandı. Bu hikâyede son sözü ben söyledim.": "Conta acertada. A última palavra desta história foi minha.",
  "Beni yendiğin geceyi her gün düşündüm. Bu gece o hayalet gitti.": "Pensei todo dia na noite em que você me venceu. Esta noite esse fantasma foi embora.",
  "İntikam tamam. {0} ile olan defter kapandı.": "Vingança completa. O capítulo {0} está encerrado.",
  "Bir kez daha kanıtladım. {opp}, üçüncü maç istersen buradayım.": "Provei mais uma vez. {opp}, se quiser uma terceira luta, estou aqui.",
  "İki kez yendim. Artık yeni isimler istiyorum.": "Te venci duas vezes. Agora quero nomes novos.",
  "Rekabet sıklet tarihine geçti.": "A rivalidade entrou para a história da categoria.",
  "Taraftarlar trilogy mi istiyor, yeni rakip mi? Tartışma başladı.": "Os fãs querem uma trilogia ou um adversário novo? O debate começou.",
  "Bu kemer {memleket}’in ve ailemin!": "Este cinturão é de {memleket} e da minha família!",
  "Çocukken hayalini kurduğum kemer şimdi belimde!": "O cinturão que eu sonhava quando criança agora está na minha cintura!",
  "Bunu bana imkânsız diyen herkese adıyorum!": "Dedico a todos que disseram que era impossível!",
  "Annen kafese koştu, kemeri beline birlikte taktınız.": "Sua mãe invadiu o octógono e vocês colocaram o cinturão juntos.",
  "Takımın seni omuzlarında taşıdı, havai fişekler patladı.": "Sua equipe te carregou nos ombros, os fogos estouraram.",
  "Aynı anda birden fazla kemer! Bunu yapabilen çok az insan var. Tarihe geçtim!": "Mais de um cinturão ao mesmo tempo! Pouquíssimos conseguiram. Eu fiz história!",
