  "🔥 İNTİKAM GECESİ: {0}, kendisini yenen {1} karşısında. İlk maç {2} lehine bitmişti. Bu sefer?": "🔥 NOITE DE VINGANÇA: {0} encara {1}, quem o venceu. A primeira luta foi de {2}. E desta vez?",
  "🔁 RÖVANŞ: {0} ve {1} yeniden karşı karşıya. İlk maçın galibi {2}. Tarih tekerrür eder mi?": "🔁 REVANCHE: {0} e {1} se reencontram. {2} venceu a primeira luta. A história vai se repetir?",
  "🏆 KEMER SAVAŞI: {0} şampiyonu {1}, tahtını yükselen isim {2}’ye karşı koruyor. 5 raunt, tek kemer.": "🏆 GUERRA PELO CINTURÃO: o campeão de {0}, {1}, defende o trono contra o nome em ascensão {2}. 5 rounds, um cinturão.",
  "🏆 UNVAN SAVUNMASI: Şampiyon {0}, aç kurt {1} karşısında. Kemer el değiştirir mi?": "🏆 DEFESA DE TÍTULO: o campeão {0} encara o lobo faminto {1}. O cinturão vai trocar de mãos?",
  "📈 YENİLMEZLİK SERİSİ: {0} {1} maçtır kaybetmiyor. {2} bu seriyi bitirecek kişi olabilir mi?": "📈 INVICTO: {0} não perde há {1} lutas. {2} será quem vai acabar com isso?",
  "⚔️ STİL SAVAŞI: {0} ustası {1} vs {2} uzmanı {3}. Vuruşçu mu kazanır, güreşçi mi?": "⚔️ CHOQUE DE ESTILOS: o mestre de {0} {1} contra o especialista em {2} {3}. Striker ou grappler?",
  "🎤 SÖZ SAVAŞI: {0} haftalardır {1} hakkında konuşuyor. Kafeste sözlerin bedeli ödenecek.": "🎤 GUERRA DE PALAVRAS: {0} fala de {1} há semanas. No octógono, palavras têm preço.",
  "📰 {0} bu hafta: {1} vs {2}. Bahisçiler {3} tarafını favori görüyor.": "📰 Esta semana no {0}: {1} vs {2}. As casas de apostas apontam {3} como favorito.",
