  "{c} sıralamada benim arkamda kalmaya alışsın. 😂": "{c} devia se acostumar a ficar atrás de mim no ranking. 😂",
  "{a} konuşacağına kafese gel. Tarih ver, oradayım.": "{a}, em vez de falar, entra no octógono. Marca a data, estarei lá.",
