  "Bugün bir gençle spar yaptım, beni çok zorladı. Gelecek parlak!": "Fiz sparring com um moleque hoje, ele me apertou. O futuro é brilhante!",
  "Buz banyosu sonrası tüm hücrelerim uyandı. 🧊": "Depois do banho de gelo, cada célula do meu corpo acordou. 🧊",
  "Yeni bir kombinasyon: jab, düşük tekme, overhand. Sıradaki rakip görecek.": "Nova combinação: jab, chute baixo, overhand. Meu próximo adversário vai ver.",
  "Antrenman bitti, protein zamanı. 🥩": "Treino encerrado, hora da proteína. 🥩",
  "Güreş hocam bugün beni 8 kez yere indirdi. Maç gecesi tersi olacak.": "Meu treinador de wrestling me derrubou 8 vezes hoje. Na noite da luta vai ser ao contrário.",
  "Gece 11’de hâlâ salondayım. Işıkları kapatan son kişi benim.": "Ainda na academia às 23h. Sou o último a apagar a luz.",
  "Kamp bitti. Şimdi sadece ağırlık ve sabır.": "Camp encerrado. Agora só peso e paciência.",
  "Kemer uyurken bile yanımda. 🏆 Sıradaki kim?": "O cinturão fica do meu lado até quando durmo. 🏆 Quem é o próximo?",
  "Sıklette herkes birbirine laf atıyor. Ben ise kemerimle kahve içiyorum. ☕🏆": "Todo mundo na categoria se xingando. Eu tomando café com meu cinturão. ☕🏆",
  "Tahtımı isteyen çok. Hak eden yok.": "Muitos querem meu trono. Nenhum merece.",
  "Kemerin ağırlığını sadece taşıyan bilir. 🏆": "Só quem carrega sabe o peso do cinturão. 🏆",
  "Listeye bakıyorum, hepsini daha önce izledim. Sıkıcı. 🥱": "Olhando a lista, já vi todos antes. Tédio. 🥱",
  "Şampiyonluk bir unvan değil, bir yaşam biçimi.": "Ser campeão não é um título, é um estilo de vida.",
  "Herkes “sıradaki” olmak istiyor. Önce sıraya girin.": "Todo mundo quer ser “o próximo”. Primeiro entrem na fila.",
  "Bir savunma daha, bir tarih daha. 👑": "Mais uma defesa, mais uma data na história. 👑",
  "{p} sosyal medyada daha iyi dövüşüyor 😂": "{p} luta melhor nas redes 😂",
