  "Amatör ligde resmi sıralama yok. Profesyonel olduğunda organizasyonunun sıklet sıralaması burada açılacak.": "Não há ranking oficial na liga amadora. Quando você virar profissional, o ranking da sua categoria aparece aqui.",
  "Bu organizasyonda sıralama yok. Tek gecelik bir fırsat: kazanırsan kapılar açılır.": "Esta organização não tem ranking. Uma chance de uma noite: vença e as portas se abrem.",
  "Resmi sıralama · Bir dövüşçüye dokun, istatistiklerini gör": "Ranking oficial · Toque num lutador para ver os atributos",
