  "Profesyonelliğe giden yolda vitrin: 8 amatör, üç maç (çeyrek final, yarı final, final). Kaybeden elenir. Şampiyon {0} ve kupayı alır; şampiyon da finalist de doğrudan profesyonel teklif alır. Davet yalnızca bir kez gelir.": "Sua vitrine rumo ao profissional: 8 amadores, três lutas (quartas, semifinal, final). Quem perde está fora. O campeão leva {0} e o troféu; campeão e finalista recebem ofertas profissionais diretas. O convite vem só uma vez.",
