  "Videoyu paylaş": "Compartilhar o vídeo",
  "Aile arasında kalsın": "Fica só na família",
  "Video bir gecede milyonlara ulaştı. Popülerlik +1, +{0} takipçi.": "O vídeo chegou a milhões numa noite. Popularidade +1, +{0} seguidores.",
  "Bu an yalnızca sizin. Videoyu her antrenmandan önce izliyorsun. Motivasyon +1.": "Este momento é só de vocês. Você vê o vídeo antes de cada treino. Motivação +1.",
  "{0} ilk adımlarını atıyor": "{0} dando os primeiros passos",
  "🗣️ İlk Kelime": "🗣️ Primeira Palavra",
  "Herkes “{0}” demesini bekliyordu. {1} televizyonda maçını görünce bağırdı: “Kafes!”": "Todos esperavam “{0}”. Ao ver sua luta na TV, {1} gritou: “Jaula!”",
  "anne": "mamãe",
  "baba": "papai",
  "Gülmekten yerlere yat": "Morrer de rir",
  "Bir de “kemer” demeyi öğret": "Ensinar também “cinturão”",
  "Bütün aile gözyaşları içinde güldü. Motivasyon +1.": "A família inteira chorou de rir. Motivação +1.",
  "İkinci kelime de geldi: “Kemer!” Motivasyon +1.": "Veio a segunda palavra: “Cinturão!” Motivação +1.",
  "{0} ve ilk kelimesi: “Kafes!”": "{0} e a primeira palavra: “Jaula!”",
  "🏟️ Tribünde İlk Kez": "🏟️ Primeira Vez na Arquibancada",
  "{0} artık üç yaşında ve bir sonraki maçını tribünden izlemek istiyor. Kulaklığı ve minik formasını şimdiden hazırlamış.": "{0} já tem três anos e quer ver sua próxima luta da arquibancada. O protetor de ouvido e a camisetinha já estão prontos.",
  "Ön sıraya bilet al": "Comprar ingresso na primeira fila",
  "Daha küçük, evden izlesin": "Ainda é pequeno, assiste em casa",
  "Kafese yürürken onu ön sırada gördün. Kulaklıkları kafasından büyüktü. Motivasyon +2, popülerlik +1.": "Indo para o octógono, você o viu na primeira fila. O protetor era maior que a cabeça. Motivação +2, popularidade +1.",
  "{0} maçı evden izledi ve televizyonun önünde senin hareketlerini taklit etti. Motivasyon +1.": "{0} assistiu de casa imitando seus golpes na frente da TV. Motivação +1.",
  "Tribündeki en küçük taraftar: {0}": "O menor torcedor da arena: {0}",
  "🎒 Okulun İlk Günü": "🎒 Primeiro Dia de Aula",
  "{0} bugün okula başlıyor. Aynı sabah sponsorunun basın toplantısı var.": "{0} começa a escola hoje. A coletiva do seu patrocinador é na mesma manhã.",
  "Okula sen götür": "Levar você mesmo à escola",
  "Basın toplantısına git": "Ir à coletiva",
  "Kapıda elini bırakmak istemedi. Sonra arkasına bakmadan koştu. Motivasyon +2.": "No portão não queria soltar sua mão. Depois correu sem olhar para trás. Motivação +2.",
  "Toplantı iyi geçti ama akşam {0} sana bütün günü tek tek anlattı ve sen orada değildin. Popülerlik +2, motivasyon -1.": "A coletiva foi bem, mas à noite {0} contou o dia todo e você não estava lá. Popularidade +2, motivação -1.",
