  "Kenardan alkışla": "Aplaudir de lado",
  "Kuşağı bağlarken ellerin titredi. Hiçbir kemer böyle hissettirmemişti. Motivasyon +2.": "Suas mãos tremiam ao amarrar. Nenhum cinturão foi assim. Motivação +2.",
