  "{0} kampından eski bir sparring ortağı aradı: rakibin oyun planını satmak istiyor.": "Um antigo sparring do camp de {0} ligou: quer vender o plano de luta.",
  "Satın al ({0})": "Comprar ({0})",
  "Reddet, böyle kazanmam": "Recusar, não venço assim",
  "Analist ekibi rakibinin son üç maçını kare kare çözdü. Hazırlıklısın.": "Os analistas destrincharam quadro a quadro as três últimas lutas do rival. Você está pronto.",
  "Zarfı aldın. İçindekilerin ne kadar doğru olduğunu kafeste göreceksin.": "Você pegou o envelope. No octógono vai ver se era verdade.",
  "Telefonu kapattın. Hocan bu kararı çok sevdi. Motivasyon +1.": "Você desligou. Seu treinador adorou a decisão. Motivação +1.",
  "Kararını verdin. Kampın bu bilgiye göre şekillendi.": "Decisão tomada. O camp foi moldado por ela.",
  "Söylentilere kulak asmadın, kendi işine baktın.": "Você ignorou os boatos e cuidou do seu.",
  "🕵️ Söylenti doğruydu: {0} sakat çıktı ve sen tam oraya hazırlandın (IQ +2).": "🕵️ O boato era verdade: {0} está machucado e você se preparou para isso (QI +2).",
  "🕵️ Söylenti blöftü: {0} sapasağlam. Planın boşa çıktı (IQ -2).": "🕵️ O boato era blefe: {0} está inteiro. Seu plano falhou (QI -2).",
  "🕵️ {0} gerçekten sakatmış ama sen planına sadık kaldın.": "🕵️ {0} estava mesmo machucado, mas você manteve o plano.",
  "🕵️ Söylenti blöftü, kanmadın. Aferin.": "🕵️ Era blefe e você não caiu. Muito bem.",
  "🕵️ {0} kiloyu zor vermiş; tempolu kampın meyvesini verecek (kondisyon +2).": "🕵️ {0} bateu o peso a duras penas; seu camp intenso vai render (cardio +2).",
  "🕵️ {0} formda geldi. Fazla tempolu kamp seni biraz yordu (kondisyon -1).": "🕵️ {0} veio em forma. O camp intenso te desgastou um pouco (cardio -1).",
