  "🕵️ {0} formda görünüyor; söylenti boşmuş.": "🕵️ {0} parece em forma; o boato era vazio.",
  "🕵️ {0} gerçekten yeni bir planla geldi ama analizin onu çözdü (IQ +2).": "🕵️ {0} veio mesmo com um plano novo, mas sua análise o decifrou (QI +2).",
  "🕵️ Analiz pahalıydı ama boşa değil: rakibi ezbere biliyorsun (IQ +2).": "🕵️ A análise foi cara, mas valeu: você conhece o rival de cor (QI +2).",
  "🕵️ {0} yeni hocasıyla bambaşka bir plan getirdi (rakip IQ +2).": "🕵️ {0} trouxe um plano totalmente diferente com o novo técnico (QI do rival +2).",
  "🕵️ Zarftaki plan doğruydu: rakibinin her hamlesini önceden biliyorsun (IQ +3).": "🕵️ O plano do envelope era real: você sabe cada movimento do rival de antemão (QI +3).",
  "🕵️ Zarftaki plan sahteydi; parayı da güveni de kaybettin (IQ -1).": "🕵️ O plano do envelope era falso; você perdeu o dinheiro e a confiança (QI -1).",
