  "{0}: 15 saniyelik bir mini oyun. İyi oynarsan bütün kamp daha verimli geçer, sakatlık riski düşer.": "{0}: um minijogo de 15 segundos. Jogue bem e o camp inteiro rende mais, com menos risco de lesão.",
