  "Alay et 😏": "Zoar 😏",
  "Karşılıklı saygı. İçin rahat, kampa odaklandın: motivasyon +1, popülerlik +1.": "Respeito mútuo. Cabeça tranquila, foco no camp: motivação +1, popularidade +1.",
  "Alaycı DM": "DM debochada",
  "Rakip mesajı paylaştı: “Saygı gösterdim, karşılığı bu.” Gündem yükseldi ama bazı hayranlar soğudu. Takipçi {0}.": "O rival postou: “Mostrei respeito e recebi isso.” O hype subiu, mas alguns fãs esfriaram. Seguidores {0}.",
  "Promotör ofisi": "Escritório do promotor",
  "Maçı satmamız lazım. Önümüzdeki hafta 3 şehirde basın turu ayarlayabiliriz. Yorucu ama bilet satışını uçurur. Var mısın?": "Precisamos vender essa luta. Dá pra montar uma turnê de imprensa em 3 cidades semana que vem. Cansa, mas os ingressos voam. Topa?",
