  "Promotör homurdandı ama kampına dokunmadın: motivasyon +1.": "O promotor resmungou, mas você protegeu o camp: motivação +1.",
  "Kamp başlamadan bu akşam baş başa bir yemek? Sonra haftalarca yüzünü göremeyeceğim. ❤️": "Um jantar a dois hoje antes do camp? Depois não te vejo por semanas. ❤️",
  "Tabii, rezervasyon benden": "Claro, eu reservo",
  "Maçtan sonra telafi ederim": "Compenso depois da luta",
  "Güzel bir akşamdı. Kafan rahat kampa girdin: motivasyon +1 (−{0}).": "Uma noite linda. Você entra no camp tranquilo: motivação +1 (−{0}).",
  "“Söz mü?” dedi. Söz verdin. Maçtan sonra unutma.": "“Promete?” Você prometeu. Não esquece depois da luta.",
  "Annem": "Mãe",
  "Oğlum yine maçın varmış, komşudan duydum. Yemeğini düzgün ye, kilo vereceğim diye kendini aç bırakma. Dua ediyorum.": "Soube pela vizinha que você tem outra luta. Come direito, não passa fome pra bater o peso. Estou rezando.",
  "Baban maçı büyük ekranda izleyecekmiş, bütün mahalleyi çağırdı. Dikkat et kendine yavrum.": "Seu pai vai ver no telão, chamou o bairro todo. Se cuida, meu bem.",
