  "“Tamam yavrum, Allah utandırmasın” yazdı. ❤️": "Ela escreveu: “Tá bom, meu bem, Deus te acompanhe.” ❤️",
  "Rakibinin stilini taklit edebilirim. Bu akşam salon kapanınca ekstra spar yapalım mı? 🥊": "Consigo imitar o estilo do seu rival. Sparring extra hoje quando a academia fechar? 🥊",
