  "Bu akşam dinlenmem lazım": "Preciso descansar hoje",
  "Sert ama faydalı bir spar. Bağınız güçlendi, biraz yıprandın (sağlık −3).": "Sparring duro, mas útil. A parceria fortaleceu, você se desgastou um pouco (saúde −3).",
  "“Peki kanka” yazdı. Biraz bozulmuş gibi.": "Ele escreveu “Beleza, mano.” Parece meio chateado.",
  "Şanslıydın. Bunu ikimiz de biliyoruz. Rövanşta gerçeği göreceksin.": "Você teve sorte. Nós dois sabemos. Na revanche você vai ver a verdade.",
  "Bu gece daha iyiydin, tebrik ederim. Bir gün rövanş isterim ama önce kendimi toparlayacağım. 🤝": "Você foi melhor hoje, parabéns. Um dia quero revanche, mas antes vou me reerguer. 🤝",
