  "{0} kemeri aldıktan sonra kadın MMA'sını dünyaya tanıttı. Onun yolunu bölüm bölüm yaşa.": "Depois de conquistar o cinturão, {0} levou o MMA feminino ao mundo. Viva o caminho dela capítulo a capítulo.",
  "{0} bu kemeri 29-0'lık yenilmez bir rekorla taşıdı. Onun yolunu bölüm bölüm yaşa.": "{0} carregou este cinturão com um cartel invicto de 29-0. Viva o caminho dele capítulo a capítulo.",
